// Pins the fork's reload contract. The channel names are frozen
// identifiers under the onevpn prefix. Upstream's pigeon bridge keeps its
// 18 channels and never names the prefix. The generated files carry the
// definition's options, and the gate regenerates and compares them. The
// Android host answers from the tunnel state. Every native wait uses the
// wait bound, and that bound sits below the Dart bound.

import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:onexray/onevpn/handover/handover.g.dart';
import 'package:onexray/onevpn/handover/handover_host.dart';

const _definitionPath = 'tool/pigeon/onevpn_handover.dart';
const _dartOutputPath = 'lib/onevpn/handover/handover.g.dart';
const _kotlinDir =
    'android/app/src/main/kotlin/net/yuandev/onexray/onevpn/handover';
const _kotlinOutputPath = '$_kotlinDir/Handover.g.kt';
const _kotlinHostPath = '$_kotlinDir/OneVpnHandoverHost.kt';
const _registrationPath =
    'android/app/src/main/kotlin/net/yuandev/onexray/onevpn/'
    'OneVpnPlatformChannel.kt';

/// Upstream's generated bridge, one file per platform.
const _upstreamOutputPaths = [
  'lib/core/pigeon/messages.g.dart',
  'android/app/src/main/kotlin/net/yuandev/onexray/pigeon/Messages.g.kt',
  'swift/App/pigeon/Messages.g.swift',
];

/// Every channel the fork contract allocates. A shipped name is frozen: the
/// Dart and native sides meet only at runtime.
const _forkChannelNames = {
  'dev.flutter.pigeon.onevpn.OneVpnHandoverFlutterApi.reloadEvent',
  'dev.flutter.pigeon.onevpn.OneVpnHandoverHostApi.reload',
  'dev.flutter.pigeon.onevpn.OneVpnHandoverHostApi.reloadSupported',
};

String _source(String path) {
  final file = File(path);
  expect(file.existsSync(), isTrue, reason: '$path is missing');
  return file.readAsStringSync();
}

/// The channel names [source] allocates: the literal prefix of each
/// generated name, before the runtime suffix.
Set<String> _channelNames(String source) =>
    RegExp(r'dev\.flutter\.pigeon\.[\w.]+')
        .allMatches(source)
        .map((m) => m.group(0)!)
        .toSet();

void main() {
  group('channel names', () {
    test('the Dart output allocates exactly the fork channels', () {
      expect(_channelNames(_source(_dartOutputPath)), _forkChannelNames);
    });

    test('the Kotlin output allocates exactly the fork channels', () {
      expect(_channelNames(_source(_kotlinOutputPath)), _forkChannelNames);
    });

    test('upstream keeps its 18 channels and never names onevpn', () {
      expect(_channelNames(_source(_upstreamOutputPaths.first)), hasLength(18));
      for (final path in _upstreamOutputPaths) {
        expect(
          _channelNames(_source(path)).where((n) => n.contains('.onevpn.')),
          isEmpty,
          reason: '$path allocates from the fork prefix',
        );
      }
    });
  });

  group('definition and outputs', () {
    late String definition;

    setUp(() => definition = _source(_definitionPath));

    test('the definition names the fork prefix, outputs and error class', () {
      for (final option in [
        "dartOut: 'lib/onevpn/handover/handover.g.dart'",
        "'$_kotlinOutputPath'",
        "package: 'net.yuandev.onexray.onevpn.handover'",
        "errorClassName: 'OneVpnHandoverError'",
        "dartPackageName: 'onevpn'",
      ]) {
        expect(definition, contains(option));
      }
      expect(definition, isNot(contains('swiftOut')));
    });

    test('both outputs come from the locked pigeon version', () {
      final locked = RegExp(r'  pigeon:\n(?:    .*\n)*?    version: "([^"]+)"')
          .firstMatch(_source('pubspec.lock'))
          ?.group(1);
      expect(locked, isNotNull);
      for (final path in [_dartOutputPath, _kotlinOutputPath]) {
        expect(
          _source(path),
          startsWith('// Autogenerated from Pigeon (v$locked)'),
          reason: '$path predates the locked pigeon. Regenerate it.',
        );
      }
    });

    test('the Kotlin output declares its own package and error class', () {
      final kotlin = _source(_kotlinOutputPath);
      expect(
        kotlin,
        contains('\npackage net.yuandev.onexray.onevpn.handover\n'),
      );
      expect(kotlin, contains('\nclass OneVpnHandoverError ('));
      expect(kotlin, isNot(contains('class FlutterError')));
    });

    test('every definition type reaches both outputs', () {
      final types = RegExp(
        r'^(?:abstract class|class|enum) (\w+)',
        multiLine: true,
      ).allMatches(definition).map((m) => m.group(1)!).toList();
      expect(types, [
        'ReloadResult',
        'ReloadTrigger',
        'ReloadPhase',
        'ReloadRequest',
        'ReloadEvent',
        'OneVpnHandoverHostApi',
        'OneVpnHandoverFlutterApi',
      ]);
      final dart = _source(_dartOutputPath);
      final kotlin = _source(_kotlinOutputPath);
      for (final type in types) {
        expect(dart, matches(RegExp('(class|enum) $type ')));
        expect(kotlin, matches(RegExp('(class|interface) $type[ (]')));
      }
    });

    test('the result codes keep their wire order', () {
      expect(ReloadResult.values.map((r) => r.name), [
        'applied',
        'rolledBack',
        'failed',
        'notRunning',
        'superseded',
        'invalidRequest',
        'timeout',
        'notSupported',
      ]);
      expect(ReloadTrigger.values.map((t) => t.name), ['settings', 'network']);
      expect(ReloadPhase.values.map((p) => p.name), ['started', 'finished']);
    });

    test('the gate regenerates the outputs and compares them', () {
      final build = _source('tool/build.sh');
      expect(build, contains('step "verify fork generated sources"'));
      expect(
        build,
        matches(RegExp(r'^tool/gen_onevpn_pigeon\.sh$', multiLine: true)),
      );
      expect(
        build,
        contains(
          'if ! generated_git diff --exit-code -- '
          '"\${FORK_GENERATED[@]}" >&2; then\n',
        ),
      );
      final generator = _source('tool/gen_onevpn_pigeon.sh');
      expect(
        generator,
        matches(
          RegExp(
            r'^dart --suppress-analytics run pigeon '
            r'--input tool/pigeon/onevpn_handover\.dart$',
            multiLine: true,
          ),
        ),
      );
      for (final path in [_dartOutputPath, _kotlinOutputPath]) {
        expect(build, contains('  $path\n'));
        expect(generator, contains('  $path\n'));
      }
    });
  });

  group('Android host', () {
    late String host;

    setUp(() => host = _source(_kotlinHostPath));

    test('the host implements the api and never answers unsupported', () {
      expect(host, contains('class OneVpnHandoverHost(\n'));
      expect(host, contains(') : OneVpnHandoverHostApi {'));
      expect(host, isNot(contains('NOT_SUPPORTED')));
    });

    test('the fork platform channel registers one host per engine', () {
      final registration = _source(_registrationPath);
      expect(
        registration,
        contains(
          'val handover = OneVpnHandoverHost(activity.applicationContext, '
          'messenger)',
        ),
      );
      expect(
        registration,
        contains('OneVpnHandoverHostApi.setUp(messenger, handover)'),
      );
      expect(
        registration.replaceAll(RegExp(r'\s+'), ' '),
        contains(
          'if (event == Lifecycle.Event.ON_DESTROY) '
          '{ handover.close() }',
        ),
      );
      expect(
        registration,
        contains(
          'fun setUp(messenger: BinaryMessenger, activity: FragmentActivity)',
        ),
      );
    });

    // Every timed wait of the handover Kotlin sources, trimmed, in file
    // order. Each native wait must use RELOAD_WAIT_MS, so the bound pin
    // below covers it. The host waits once, for the finished event.
    test('every native wait uses RELOAD_WAIT_MS', () {
      final dir = Directory(_kotlinDir);
      final lines = [
        for (final file
            in dir.listSync().whereType<File>().toList()
              ..sort((a, b) => a.path.compareTo(b.path)))
          if (file.path.endsWith('.kt'))
            for (final line in file.readAsLinesSync())
              if (RegExp(r'withTimeout\w*\(').hasMatch(line)) line.trim(),
      ];
      expect(lines, const [
        'return withTimeout(RELOAD_WAIT_MS) { finished.await() }',
      ]);
      expect(
        lines.where((line) => !line.contains('withTimeout(RELOAD_WAIT_MS)')),
        isEmpty,
      );
    });

    test('the native wait sits below the Dart bound', () {
      final wait = RegExp(r'const val RELOAD_WAIT_MS: Long = ([\d_]+)L')
          .firstMatch(host)
          ?.group(1);
      expect(wait, isNotNull);
      final nativeMs = int.parse(wait!.replaceAll('_', ''));
      expect(
        OneVpnHandoverDeadlines.nativeReload,
        Duration(milliseconds: nativeMs),
      );
      expect(
        OneVpnHandoverDeadlines.reload - OneVpnHandoverDeadlines.nativeReload,
        const Duration(seconds: 5),
      );
    });
  });
}
